from collections import Counter

def transform(grid):
    R, C = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    bg = Counter(flat).most_common(1)[0][0]
    # connected components of non-bg cells
    seen = [[False]*C for _ in range(R)]
    comps = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg and not seen[r][c]:
                stack = [(r, c)]
                seen[r][c] = True
                comp = []
                while stack:
                    x, y = stack.pop()
                    comp.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < R and 0 <= ny < C and not seen[nx][ny] and grid[nx][ny] != bg:
                            seen[nx][ny] = True
                            stack.append((nx, ny))
                comps.append(comp)
    # seed = largest component (noise cells are isolated singletons)
    seed = max(comps, key=len)
    # anchor is the cell with color 1
    anchor = None
    for (r, c) in seed:
        if grid[r][c] == 1:
            anchor = (r, c)
    ar, ac = anchor
    offsets = [((r-ar, c-ac), grid[r][c]) for (r, c) in seed]
    noise_color = None
    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg and (r, c) not in set(seed):
                noise_color = grid[r][c]
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == noise_color:
                for (dr, dc), col in offsets:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < R and 0 <= nc < C:
                        out[nr][nc] = col
    return out
